<?php $m=$args['model']??array();$p=$m['profile']??array();$catalogue=(array)($m['instruments']??array());$days=(array)($m['day_offs']??array());$accepting=$m['accepting_state']->state??'';$weekly_minutes=0;foreach((array)($m['availability']??array()) as $r){if(($r['state']??'')==='blocked')continue;$a=explode(':',(string)($r['start']??''));$b=explode(':',(string)($r['end']??''));$start=((int)($a[0]??0))*60+(int)($a[1]??0);$end=($r['end']??'')==='24:00'?1440:((int)($b[0]??0))*60+(int)($b[1]??0);if($end>$start)$weekly_minutes+=$end-$start;}$golden=[];$regions=class_exists('\\Delnavazan\\Platform\\Core\\Application\\AcademyDemandWindowRule')?\Delnavazan\Platform\Core\Application\AcademyDemandWindowRule::regions():[];try{$teacherZone=new DateTimeZone($p['timezone']??'UTC');foreach($regions as $region){$zone=new DateTimeZone($region['timezone']);$monday=(new DateTimeImmutable('next monday',$zone))->setTime(0,0);$start=new DateTimeImmutable($monday->format('Y-m-d').' '.$region['start'],$zone);$end=new DateTimeImmutable($monday->format('Y-m-d').' '.$region['end'],$zone);$golden[]=[$region['label'],$start->setTimezone($teacherZone)->format('D H:i').'–'.$end->setTimezone($teacherZone)->format('H:i')];}}catch(Throwable){$golden=[];} ?>
